using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Agents.AI;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Build the IChatClient via MEAI abstraction ---
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Define tools ---
var tools = new List<AITool>
{
    AIFunctionFactory.Create(WebSearch),
    AIFunctionFactory.Create(SaveNote),
    AIFunctionFactory.Create(GetNotes),
};

// --- Create the research agent ---
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. When given a topic, you:
        1. Search the web multiple times to gather diverse information.
        2. Save important findings as notes using the SaveNote tool.
        3. After gathering enough information, retrieve all notes and produce
           a concise, well-structured summary of your findings.
        Always cite your sources. Be thorough but concise.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and summarizing findings.",
    tools: tools);

// --- Run the agent ---
Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}");

// Display the final response
foreach (var message in response.Messages)
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
    {
        Console.WriteLine(message.Text);
    }
}

// --- Tool implementations ---

// In-memory note store
List<string> _notes = [];

[Description("Search the web for information on a query. Returns search results as text.")]
static string WebSearch([Description("The search query")] string query)
{
    // Simulated web search - in production, wire up to Bing Search API or similar
    Console.WriteLine($"  [Tool] Searching web for: \"{query}\"");
    return $"""
        Search results for "{query}":
        1. Wikipedia - Overview article covering key aspects of {query}.
           Source: https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}
        2. Research paper - Recent findings and developments related to {query}.
           Source: https://arxiv.org/search/?query={Uri.EscapeDataString(query)}
        3. News article - Latest news and updates about {query}.
           Source: https://news.example.com/{Uri.EscapeDataString(query)}
        (Note: This is a simulated search. Connect to a real search API for production use.)
        """;
}

[Description("Save an important finding or note for later summarization.")]
string SaveNote(
    [Description("The title or label for this note")] string title,
    [Description("The content of the note")] string content)
{
    var note = $"[{title}]: {content}";
    _notes.Add(note);
    Console.WriteLine($"  [Tool] Saved note: \"{title}\"");
    return $"Note saved successfully: \"{title}\"";
}

[Description("Retrieve all saved notes to compile the final summary.")]
string GetNotes()
{
    Console.WriteLine($"  [Tool] Retrieving {_notes.Count} note(s)");
    if (_notes.Count == 0)
        return "No notes saved yet.";

    return string.Join("\n\n", _notes);
}

